    pub fn type_fileio_async() {
        let mut h = Harness::new();
        let temp = Harness::temp_dir("fileio");
        let _ = &temp;
        let mut r: Vec<Value> = Vec::new();
        r.push(h.await_static("Windows.Storage.StorageFolder", "getFolderFromPathAsync", &[s(&temp)]).unwrap_or_else(|e| panic!("getFolderFromPathAsync: {e}")));
        r.push(h.await_call(handle(r[0].clone()), "createFileAsync", &[s("io.txt"), s("replace-existing")]).unwrap_or_else(|e| panic!("createFileAsync: {e}")));
        r.push(h.await_static("Windows.Storage.FileIO", "writeTextAsync", &[r[1].clone(), s("line")]).unwrap_or_else(|e| panic!("writeTextAsync: {e}")));
        r.push(h.await_static("Windows.Storage.FileIO", "appendTextAsync", &[r[1].clone(), s(" two")]).unwrap_or_else(|e| panic!("appendTextAsync: {e}")));
        r.push(h.await_static("Windows.Storage.FileIO", "readTextAsync", &[r[1].clone()]).unwrap_or_else(|e| panic!("readTextAsync: {e}")));
        assert_eq!(r.last().unwrap(), &s("line two"));
    }

