    pub fn type_storagefolder_async() {
        let mut h = Harness::new();
        let temp = Harness::temp_dir("storagefolder");
        let _ = &temp;
        let w = handle(h.await_static("Windows.Storage.StorageFolder", "getFolderFromPathAsync", &[s(&temp)]).unwrap());
        let mut r: Vec<Value> = Vec::new();
        r.push(h.await_call(w, "createFileAsync", &[s("n4.txt"), s("replace-existing")]).unwrap_or_else(|e| panic!("createFileAsync: {e}")));
        r.push(h.await_static("Windows.Storage.FileIO", "writeTextAsync", &[r[0].clone(), s("hello from svelters")]).unwrap_or_else(|e| panic!("writeTextAsync: {e}")));
        r.push(h.await_static("Windows.Storage.FileIO", "readTextAsync", &[r[0].clone()]).unwrap_or_else(|e| panic!("readTextAsync: {e}")));
        assert_eq!(r.last().unwrap(), &s("hello from svelters"));
        let err = h.await_call(w, "getFileAsync", &[s("missing.txt")]).unwrap_err();
        assert!(err.contains("winrt"), "a WinRT NativeError: {err}");
    }

    pub fn type_storagefolder_lifetime() {
        let mut h = Harness::new();
        let temp = Harness::temp_dir("storagefolder");
        let _ = &temp;
        let w = handle(h.await_static("Windows.Storage.StorageFolder", "getFolderFromPathAsync", &[s(&temp)]).unwrap());
        let before = h.live_handles();
        h.destroy(w);
        assert!(h.info(w).is_err(), "stale after destroy");
        assert_eq!(h.live_handles(), before - 1, "one handle released");
    }

